"""Generator of the synthetic pump-designation test set (invented strings only)."""
import json
import pathlib
import random
OUT = pathlib.Path(__file__).resolve().parent / 'parser_synthetic.jsonl'
ДВОЙНИКИ = dict(zip('АВЕКМНОРСТХ', 'ABEKMHOPCTX'))
Q_ПУЛ = [37, 53, 77, 93, 117, 143, 171, 211, 267]
H_ПУЛ = [1873, 2041, 2318, 1657, 2493, 1789, 2167, 2644, 1931]
МИН_Q, МАКС_Q, МИН_H, МАКС_H = (5, 1500, 300, 3500)

def истина(форма, сер=None, Q=None, H=None, qlo=None, qhi=None, гом=False):
    return dict(форма=форма, серия=сер, Q=Q, Q_min=qlo, Q_max=qhi, H=H, гомоглиф=гом)

def A(сер, Q, H, sep='-', строка=None, гом=False):
    return (строка or f'{сер}{sep}{Q}{sep}{H}', истина('A', сер, Q, H, гом=гом))

def B(Q, H, sep='/'):
    return (f'{Q}{sep}{H}', истина('B', None, Q, H))

def C(сер, Q, sep='-', строка=None):
    return (строка or f'{сер}{sep}{Q}', истина('C', сер, Q, None))

def D(сер, lo, hi, H, sep='-', sepr='/'):
    return (f'{сер}{sep}{lo}{sepr}{hi}{sep}{H}', истина('D', сер, None, H, lo, hi))

def E(s):
    return (s, истина('E'))
F = ('', истина('F'))

def канон_сер(s):
    s = ''.join((ch for ch in s.upper() if ch not in ' -.'))
    return ''.join((ДВОЙНИКИ.get(ch, ch) for ch in s))

def сравнение(a, b):
    if a['форма'] in 'EF' or b['форма'] in 'EF':
        return 'в'
    if (a['серия'] is None) != (b['серия'] is None):
        return 'в'
    ка = (канон_сер(a['серия'] or ''), a['Q'], a['Q_min'], a['Q_max'], a['H'])
    кб = (канон_сер(b['серия'] or ''), b['Q'], b['Q_min'], b['Q_max'], b['H'])
    return 'а' if ка == кб else 'б'

def ожидание(до, по):
    случай = сравнение(до, по)
    Q, H = (по['Q'], по['H'])
    мощность = None
    if случай == 'б' and Q is not None and (H is not None) and (МИН_Q <= Q <= МАКС_Q) and (МИН_H <= H <= МАКС_H):
        мощность = Q * H
    return dict(случай=случай, произв=Q, напор=H, мощность=мощность)
РЯДЫ = []

def добавить(класс, до, по, заметка=''):
    РЯДЫ.append(dict(класс=класс, до_насос=до[0], после_насос=по[0], истина_до=до[1], истина_после=по[1], заметка=заметка))
r = random.Random(20261008)
