добавить('регистр и пробелы', A('ЭЦН', 53, 2041, строка=' эцн-53-2041'), A('ЭЦН', 53, 2041))
добавить('регистр и пробелы', A('ЭЦН', 53, 2041, строка='эцн 53 2041'), A('ЭЦН', 77, 2041, строка='ЭЦН-77-2041'))
for k, ряд in enumerate(РЯДЫ, 1):
    ряд['id'] = f's{k:04d}'
    ряд['ожидание'] = ожидание(ряд['истина_до'], ряд['истина_после'])
with open(OUT, 'w', encoding='utf-8') as f:
    for ряд in РЯДЫ:
        f.write(json.dumps({'id': ряд['id'], **{k: v for k, v in ряд.items() if k != 'id'}}, ensure_ascii=False) + '\n')
print(len(РЯДЫ), 'строк ->', OUT)
